OPENQASM 3.0;
include "stdgates.inc";
bit[4] c;
qubit[8] q;

// 1. Custom gate definition (Parser should skip this entire block)
gate my_custom_h a {
    u(pi/2, 0, pi) a;
}

// 2. Standard single-qubit gates with various parameter formats
h q[0];
rx(1.57079632679) q[1];
rz(-pi/2) q[2];

// 3. Specific barrier
barrier q[0], q[1], q[2];

// 4. Standard multi-qubit gates
cx q[0], q[1];
ccx q[0], q[1], q[2];
cswap q[2], q[3], q[4];

// 5. QASM 3.0 Modifiers (Testing your dynamic control counting)
ctrl @ x q[4], q[5];
ctrl(3) @ rx(pi) q[0], q[1], q[2], q[5], q[6];
ctrl @ ctrl @ z q[5], q[6], q[7];

// 6. Global barrier (Should map to all known active wires)
barrier;

// 7. Measurements
c[0] = measure q[0];
c[1] = measure q[7];

